ev("rg1","2025-02-05","에코백스",RG,"비즈한국은 2024년 미국에서 에코백스 일부 제품이 해킹돼 욕설을 하거나 반려견을 따라다닌 사례가 있었고, 에코백스 CEO가 클라우드가 아닌 개별 기기의 피해였으며 각 국가 보안 기준을 따른다고 밝혔다고 전했다. 기사는 중국 제품의 약점으로 보안과 AS 접근성을 꼽았다.",["bz2502"],tags=["보안"],imp=2,flags=["미국 사례이며 국내 사고는 아님","해킹 경위는 에코백스 설명을 따름"])
ev("rg2","2025-03-04","개인정보보호위원회",RG,"개인정보보호위원회가 3월 4일 삼성전자, LG전자, 샤오미, 에코백스, 로보락의 로봇청소기를 대상으로 개인정보 수집·관리 실태를 사전 점검한다고 발표했다. 점검 계기는 로보락 처리방침 문구 논란이다.",["pi_jd2503","pi_et2503","pi_fn2503"],tags=["개인정보"],imp=3,flags=["드리미는 점검 대상 5개 브랜드에 포함되지 않음"])
ev("rg3","2025-03-11","에코백스",RG,"전자신문은 브랜드별 처리방침을 비교했다. 에코백스는 알리바바클라우드와 바이두 등 중국 업체로의 전송과 싱가포르 저장을, 드리미는 미국·독일·싱가포르 데이터센터 사용과 불명확한 수집 항목을 적었다고 전했다.",["pi_et2503"],tags=["개인정보"],imp=3,flags=["처리방침 조항의 원문은 직접 확인하지 못함"])
ev("rg4","2025-06-29","한국인터넷진흥원",RG,"머니투데이방송은 KISA IoT 보안인증이 누적 413건이고 전년 106건(전전년 82건)이며, 중국산 로봇청소기의 인증은 0건이라고 전했다. 인증은 의무가 아니고 벌칙도 없다.",["pi_mtn2506"],tags=["보안인증"],imp=3,flags=["연도별 수치의 기준 연도는 기사 서술을 따름","KISA 원본 통계는 직접 확인하지 못함"])
ev("rg5","2025-09-02","한국소비자원",RG,"한국소비자원과 KISA가 로봇청소기 6개 제품의 40개 항목을 점검했다(조사 2025-03~07). 로보락 S9 맥스V 울트라는 전 항목 우수 또는 양호였고, 드리미 X50 울트라는 카메라 강제 작동과 개인정보 노출 우려가 지적됐다. 에코백스 X8 프로 옴니 등은 사진 조회 우려가 지적됐고 삼성·LG는 상대적으로 우수했다. 업체들은 즉시 조치했고 에코백스는 7월 자체 조치를 했다.",["pi_sg2509","pi_hk2509"],tags=["보안","점검"],imp=3,flags=["6개 중 나머지 제품은 이번 질문 브랜드 범위 밖","'우수/양호' 평가 기준 상세와 지적 항목의 정확한 이름은 기사 서술을 따름"])
ev("rg6","2024-12","삼성전자",RG,"파이낸셜뉴스는 삼성 로봇청소기가 2024년 12월 개인정보 보호 설계 인증을 받았다고 전했다.",["pi_fn2503"],tags=["개인정보 인증"],flags=["중국 브랜드 값이 아닌 비교 참고","인증 명칭과 인증기관은 기사 서술을 따름"],imp=2)
ev("rg7","2026-09-14","개인정보보호위원회",RG,"개인정보보호위원회가 로보락, 삼성, LG, 에코백스, 샤오미 점검 결과 특별한 침해 위험은 없었다고 밝혔다. 일부 국외 이전 고지가 미흡하고 국내대리인을 지정하지 않은 사례가 있어 시정 권고를 의결했고, 최신 모델은 보안 조치가 완료됐다. 2026년 하반기 신기능을 점검하고 연말 AI·IoT 프라이버시 기술 분석센터를 개소할 계획이다.",["pi_mtn2609"],tags=["개인정보"],imp=3,flags=["점검 대상 5개 브랜드의 표기가 로보락·삼성·LG·에코백스·샤오미로 2025-03 발표와 같은지 원문 확인 필요","시정 권고 대상 브랜드는 기사에 구분이 없음"])
